-- G21: versioned passage QA Gates A-D and H; hard failures cannot be averaged away.
create table public.passage_qa_versions(id uuid primary key default gen_random_uuid(),version text unique not null,gate_config jsonb not null,status text not null check(status in('draft','active','retired')),activated_at timestamptz,created_at timestamptz not null default now(),check((status='active')=(activated_at is not null)));
insert into public.passage_qa_versions(version,gate_config,status,activated_at) values('1.0.0','{"gates":["A","B","C","D","H"],"duplicate_max":0.88,"naturalness_min":0.7,"engagement_min":0.6,"hard_failure_policy":"fail_closed"}','active',now());
create table public.passage_qa_results(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.contract_generation_candidates(id) on delete restrict,qa_version_id uuid not null references public.passage_qa_versions(id) on delete restrict,decision text not null check(decision in('pass','fail','human_review')),analysis_snapshot jsonb not null,checks jsonb not null,hard_failures jsonb not null,soft_failures jsonb not null,gate_results jsonb not null,explanation jsonb not null,evaluator_provider text not null,evaluator_model text not null,evaluator_payload jsonb not null,latency_ms integer not null check(latency_ms>=0),created_at timestamptz not null default now(),unique(candidate_id,qa_version_id));
create table public.passage_qa_check_results(id uuid primary key default gen_random_uuid(),qa_result_id uuid not null references public.passage_qa_results(id) on delete cascade,gate text not null check(gate in('A','B','C','D','H')),rule_key text not null,passed boolean not null,hard_failure boolean not null,expected jsonb,actual jsonb,created_at timestamptz not null default now(),unique(qa_result_id,gate,rule_key));
alter table public.passage_qa_versions enable row level security;alter table public.passage_qa_results enable row level security;alter table public.passage_qa_check_results enable row level security;create policy passage_qa_version_read on public.passage_qa_versions for select using(status='active' or public.is_platform_admin());create policy passage_qa_staff_read on public.passage_qa_results for select using(public.is_staff());create policy passage_qa_checks_staff_read on public.passage_qa_check_results for select using(public.is_staff());grant select on public.passage_qa_versions,public.passage_qa_results,public.passage_qa_check_results to authenticated;
comment on table public.passage_qa_check_results is 'Atomic gate evidence. Any failed hard rule forces passage QA failure regardless of aggregate quality scores.';
